	private static Node primitive(Node occurrence) {
		Node child = occurrence;
		for (Node parent = occurrence.jjtGetParent(); parent != null; parent = child.jjtGetParent()) {
			if (parent instanceof ASTGraphGraphPattern && parent.jjtGetChild(0) == child) {
				return parent;
			}
			if (parent instanceof ASTTriplesSameSubjectPath) {
				return parent;
			}
			if (parent instanceof ASTBind || parent instanceof ASTConstraint || parent instanceof ASTProjectionElem
					|| parent instanceof ASTServiceGraphPattern) {
				return null;
			}
			child = parent;
		}
		return null;
	}

	private static Node bindingOperand(Node primitive) {
		if (primitive instanceof ASTTriplesSameSubjectPath) {
			for (Node parent = primitive.jjtGetParent(); parent != null; parent = parent.jjtGetParent()) {
				if (parent instanceof ASTBasicGraphPattern) {
					// A blank-node label belongs to this whole lexical BGP, even across several triple subjects.
					return parent;
				}
			}
		}
		return primitive;
	}

	private static boolean isServiceSelector(Node occurrence) {
		return occurrence.jjtGetParent() instanceof ASTServiceGraphPattern service
				&& service.jjtGetChild(0) == occurrence;
	}

	private static boolean isTermSlot(Node occurrence) {
		if (isServiceSelector(occurrence)) {
			return true;
		}
		for (Node parent = occurrence.jjtGetParent(); parent != null; parent = parent.jjtGetParent()) {
			if (parent instanceof ASTTripleTerm || parent instanceof ASTReifiedTriple) {
				return true;
			}
			if (parent instanceof ASTBind || parent instanceof ASTConstraint || parent instanceof ASTProjectionElem
					|| parent instanceof ASTServiceGraphPattern) {
				// A SERVICE body keeps the grammar roles of its own expressions and declarations.
				return false;
			}
		}
		return false;
	}

	private static boolean validPosition(Var variable, Value value) {
		QueryModelNode parent = variable.getParentNode();
		if (parent instanceof StatementPattern statement) {
			// Literal path endpoints are legal syntax, and generated positive-length child statements do not
			// describe the validity of their nullable lexical path. The endpoint evaluator enforces RDF roles.
			return variable != statement.getPredicateVar() || value instanceof IRI;
		}
		if (parent instanceof TripleRef triple) {
			return (variable != triple.getSubjectVar() || value instanceof Resource)
					&& (variable != triple.getPredicateVar() || value instanceof IRI);
		}
		return !(parent instanceof Graph graph && variable == graph.getGraphName())
				|| value instanceof IRI || value instanceof BNode;
	}

	private static void verifyReplacedOutputs(Node syntax, Set<String> outputs, SourceProvenance provenance,
			Map<SourceRange, String> edits) {
		if (syntax instanceof ASTVar variable && outputs.contains(variable.getName())
				&& !edits.containsKey(provenance.range(syntax))) {
			throw unsupported("a captured output still has an unbound occurrence in its relation");
		}
		for (int index = 0; index < syntax.jjtGetNumChildren(); index++) {
			verifyReplacedOutputs(syntax.jjtGetChild(index), outputs, provenance, edits);
		}
	}

	private static void collectWildcards(Node syntax, Set<ASTSelect> result) {
		if (syntax instanceof ASTSelect select && select.isWildcard()) {
			result.add(select);
		}
		for (int index = 0; index < syntax.jjtGetNumChildren(); index++) {
			collectWildcards(syntax.jjtGetChild(index), result);
		}
	}

	private static boolean contains(SourceRange outer, SourceRange inner) {
		return outer.start() <= inner.start() && outer.end() >= inner.end();
	}

	private static void put(Map<SourceRange, String> edits, SourceRange range, String replacement) {
		String previous = edits.putIfAbsent(range, replacement);
		if (previous != null && !previous.equals(replacement)) {
			throw unsupported("derived source occurrences disagree");
		}
	}

	private static String term(Value value) {
		StringBuilder result = new StringBuilder();
		SPARQLQueries.appendBindingValue(value, result);
		return result.toString();
	}

	private static QueryEvaluationException unsupported(String reason) {
		return new QueryEvaluationException("Unsupported prepared binding transport: " + reason);
	}

	record Result(String source) {
	}

	private static void validateRestorations(TupleExpr root, List<Restore> restores) {
		if (restores.isEmpty()) {
			return;
		}
		QueryAlgebraBindingAnalysis actual = QueryAlgebraBindingAnalysis.withBindingValues(root,
				EmptyBindingSet.getInstance());
		for (Restore restore : restores) {
			validateAssociativeAssignments(actual, restore, restores);
			var input = actual.contextAt(restore.owner());
			if (!input.bindingDomainKnown() || input.maybeBoundNames().contains(restore.name())
					&& (!input.guaranteedNames().contains(restore.name())
							|| !restore.value().equals(input.fixedValues().get(restore.name())))) {
				throw unsupported("a captured relation output would overwrite an incoming binding: "
						+ restore.name());
			}
		}
	}

	/**
	 * Ordinary joins may reorder their associative operands, so both lexical VALUES orders need the same admission.
	 * This is the same flattening boundary used by the join optimizer: a nested scoped join remains one operand.
	 * Non-join operators, including assignments, OPTIONAL, UNION, MINUS, subqueries and GRAPH, keep their own frames.
	 */
	private static void validateAssociativeAssignments(QueryAlgebraBindingAnalysis analysis, Restore restore,
			List<Restore> restores) {
		TupleExpr region = (TupleExpr) restore.owner();
		while (region.getParentNode() instanceof Join parent && !TupleExprs.requiresIndependentEvaluation(region)) {
			region = parent;
		}
		Set<QueryModelNode> captured = Collections.newSetFromMap(new IdentityHashMap<>());
		for (Restore other : restores) {
			if (restore.name().equals(other.name()) && restore.value().equals(other.value())) {
				captured.add(other.owner());
			}
		}
		validateAssociativeAssignments(analysis, region, true, restore, captured);
	}

	private static void validateAssociativeAssignments(QueryAlgebraBindingAnalysis analysis, TupleExpr operand,
			boolean root, Restore restore, Set<QueryModelNode> captured) {
		if (captured.contains(operand)) {
			// Source-owned captures already fix this output, including nullable path algebra whose internal
			// relations are not independent lexical operands. Admission concerns only their local peers.
			return;
		}
		if (operand instanceof Join join && (root || !join.isVariableScopeChange())) {
			validateAssociativeAssignments(analysis, join.getLeftArg(), false, restore, captured);
			validateAssociativeAssignments(analysis, join.getRightArg(), false, restore, captured);
		} else if (!analysis.producesOnlyAbsentOrEqual(operand, restore.name(), restore.value())) {
			throw unsupported("a captured relation output would overwrite an incoming binding: " + restore.name());
		}
	}

	private record Restore(QueryModelNode owner, String name, Value value, SourceRange primitive) {
	}

	private static final class Primitive {
		final SourceRange range;
		final Map<String, Value> outputs = new LinkedHashMap<>();
		boolean empty;

		Primitive(SourceRange range) {
			this.range = range;
		}
	}
